<script setup lang="ts">withDefaults(defineProps<{modelValue?:number|null;currency?:string;locale?:string;label?:string;min?:number;max?:number}>(),{currency:'USD',locale:'en-US'});const emit=defineEmits<{'update:modelValue':[value:number|null]}>();</script><template><label class="vx-native-field"><span v-if="label">{{label}}</span><div class="vx-currency-field"><span>{{currency}}</span><input class="vx-control" type="number" step="0.01" :value="modelValue??''" :min="min" :max="max" inputmode="decimal" @input="emit('update:modelValue',($event.target as HTMLInputElement).value===''?null:Number(($event.target as HTMLInputElement).value))"/></div></label></template>